import { candidates,firstSeries,secondSeries,institutes,polls } from './data/mock.js';
import { runoffForecast,currentComparisons,flavioMinusLula } from './data/comparison.js';
import { instituteSeries } from './data/institute-series.js';
import { locale,translate,observeTranslations } from './i18n.js';
import { mountPageRail,addLanguageSwitch } from './layout.js';

const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=(t,year=false)=>new Intl.DateTimeFormat(locale,{day:'numeric',month:'short',...(year?{year:'numeric'}:{}),timeZone:'UTC'}).format(new Date(t));
const stamp=t=>new Date(t).toISOString().slice(0,16).replace('T',' ')+' UTC';
const pct=n=>new Intl.NumberFormat(locale,{minimumFractionDigits:1,maximumFractionDigits:1}).format(n)+'%';
const marketPct=n=>new Intl.NumberFormat(locale,{minimumFractionDigits:1,maximumFractionDigits:2}).format(n)+'%';
const seriesInk=color=>`var(--series-${({'#501C72':'purple','#328088':'teal','#A06425':'ochre','#707888':'slate','#737C8E':'slate','#AD7DAC':'mauve'}[color]||'purple')},${color})`;
const labelInk=color=>`var(--label-${({'#501C72':'purple','#328088':'teal','#A06425':'ochre','#707888':'slate','#737C8E':'slate','#AD7DAC':'mauve'}[color]||'purple')},${color})`;
const signed=n=>(n>0?'+':'')+Number(n).toFixed(1);
const arrow='<svg class="arrow-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><path d="M4 12h15M13 6l6 6-6 6"/></svg>';
const wordmark='<span class="initial">T</span>HE <span class="initial">M</span>ACHINE <span class="initial">O</span>BSERVER';
const pages=[['index','Predict victory'],['first-round','First round'],['second-round','Second round'],['bet-markets','Bet markets'],['offenders','Offenders'],['methodology','Methodology'],['database','Database']];
const page=document.body.dataset.page;
const link=(href,label,primary=false)=>`<a class="${primary?'button primary':'text-link'}" href="${href}">${label}${arrow}</a>`;
const intro=(title,description,type='Illustrative data')=>`<section class="page-intro"><div><h1>${title}</h1><p>${description}</p></div><div class="page-meta"><span class="badge">${type}</span><br>Design edition · 19 September 2026</div></section>`;
const segment=(id,values,active)=>`<div class="segmented" role="group" aria-label="${id}">${values.map(x=>`<button type="button" data-range="${x}" aria-pressed="${x===active}">${x}</button>`).join('')}</div>`;
const sourceFooter=(text,actions='')=>`<div class="chart-footer"><p>${text}</p><div class="actions">${actions}</div></div>`;
const downloadButton=(id,label='Download CSV')=>`<button class="link-button" id="${id}" type="button">${label}</button>`;
const chartShell=id=>`<div class="chart-wrap" id="${id}"></div>`;

$('#app').innerHTML=`<div class="prototype-strip">LOCAL DESIGN PROTOTYPE · Polling & forecast figures are illustrative. Markets use an archived snapshot.</div><header class="container"><div class="masthead"><div class="edition"><strong>BRAZIL · 2026</strong><br>Presidential election observatory</div><a class="wordmark" aria-label="The Machine Observer home" href="index.html">${wordmark}</a><div class="edition right"><strong>Evidence before certainty.</strong><br>Independent views of the race</div></div><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">${pages.find(x=>x[0]===page)?.[1]}<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M4 7h16M4 12h16M4 17h16"/></svg></button><nav id="navigation" class="main-nav" aria-label="Main navigation">${pages.map(([slug,title])=>`<a href="${slug}.html" ${page===slug?'aria-current="page"':''}>${title}</a>`).join('')}</nav></header><main class="container" id="main"></main><footer class="site-footer container"><div><a class="wordmark footer-wordmark" href="index.html">${wordmark}</a><p>Brazil’s presidential race, examined. A local visual prototype: no forecast model or institute assessment is operating here.</p></div><div class="footer-right"><a href="methodology.html">How to read the numbers</a><a href="database.html">Explore the evidence</a><p>Prototype v0.1 · Mock polling data · Archived market data<br>Not deployed · No production update routines connected</p></div></footer>`;
$('.menu-toggle').addEventListener('click',e=>{const btn=e.currentTarget;const open=btn.getAttribute('aria-expanded')!=='true';btn.setAttribute('aria-expanded',open);$('#navigation').classList.toggle('open',open)});
const header=$('header'),headerInner=document.createElement('div');
headerInner.className='container';headerInner.append(...header.childNodes);header.append(headerInner);header.className='site-header';
new ResizeObserver(()=>document.documentElement.style.setProperty('--header-height',`${header.offsetHeight}px`)).observe(header);

function csvDownload(filename,rows){
  const content=rows.map(row=>row.map(v=>{let s=String(v??'');if(/^[=+@]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}).join(',')).join('\r\n');
  const url=URL.createObjectURL(new Blob(['\uFEFF'+content],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);
}
function seriesCSV(series){const times=[...new Set(series.flatMap(s=>s.points.map(p=>p.t)))].sort((a,b)=>a-b);const maps=series.map(s=>new Map(s.points.map(p=>[p.t,p.p])));return [['timestamp_utc',...series.map(s=>s.name)],...times.map(t=>[new Date(t).toISOString(),...maps.map(m=>m.get(t)??'')])];}

// Responsive, accessible native SVG chart. No smoothing or fabricated interpolation.
function drawChart(host,series,{min=0,max=60,step=10,band=false,threshold=null,title='Time series',unit='%',market=false,maxGap=Infinity,domain=null,square=false}={}){
  const width=Math.max(240,host.clientWidth||900),narrow=width<600,L=34,R=(narrow||square)?18:154,T=22,B=35,W=width-L-R,H=square?W+T+B:(narrow?310:350),PH=H-T-B;
  const observations=series.flatMap(s=>s.points).filter(p=>Number.isFinite(p.t));
  if(!observations.length){host.innerHTML='<div class="empty-state"><h3>No series selected</h3><p>Select a candidate above to show the chart.</p></div>';return;}
  let [start,end]=domain||[Math.min(...observations.map(p=>p.t)),Math.max(...observations.map(p=>p.t))];if(start===end)end=start+86400000;
  const x=t=>L+(t-start)/(end-start)*W, y=p=>T+(max-p)/(max-min)*PH;
  const grid=[];for(let v=min;v<=max+.01;v+=step)grid.push(`<line class="${v===0?'zero-line':'axis-line'}" x1="${L}" x2="${L+W}" y1="${y(v)}" y2="${y(v)}"/><text x="${L-8}" y="${y(v)+4}" text-anchor="end">${v}${v===max&&unit==='%'?'%':''}</text>`);
  const xTicks=Array.from({length:narrow?4:6},(_,i)=>start+(end-start)*i/(narrow?3:5));
  const tickDate=t=>end-start>185*86400000?new Intl.DateTimeFormat(locale,{month:'short',year:narrow?'2-digit':'numeric',timeZone:'UTC'}).format(new Date(t)):date(t);
  const axis=xTicks.map(t=>`<text x="${x(t)}" y="${H-9}" text-anchor="${t===start?'start':t===end?'end':'middle'}">${end-start<2*86400000?new Date(t).toISOString().slice(11,16):tickDate(t)}</text>`).join('');
  const last=series.map(s=>({s,p:[...s.points].reverse().find(p=>Number.isFinite(p.p))})).filter(d=>d.p).sort((a,b)=>b.p.p-a.p.p);
  const labelYs=[];last.forEach((d,i)=>labelYs[i]=Math.max(y(d.p.p),i?labelYs[i-1]+23:T+4));
  if(labelYs.at(-1)>H-B) {const excess=labelYs.at(-1)-(H-B);for(let i=0;i<labelYs.length;i++)labelYs[i]-=excess;}
  const paths=series.map((s,si)=>{
    let prev=null;let path='';for(const p of s.points){if(!Number.isFinite(p.p)){prev=null;continue;}const gap=prev&&p.t-prev.t>maxGap;path+=(prev&&!gap?'L':'M')+x(p.t).toFixed(2)+','+y(p.p).toFixed(2);prev=p;}
    const finite=s.points.filter(p=>Number.isFinite(p.p));
    const region=band&&si<2&&finite.length?`<path d="M${finite.map(p=>`${x(p.t)},${y(Math.min(max,p.p+2.3))}`).join('L')}L${[...finite].reverse().map(p=>`${x(p.t)},${y(Math.max(min,p.p-2.3))}`).join('L')}Z" fill="${seriesInk(s.color)}" opacity=".075"/>`:'';
    const isolated=market?finite.filter(p=>{const j=s.points.indexOf(p),before=s.points[j-1],after=s.points[j+1];return (!before||!Number.isFinite(before.p)||p.t-before.t>maxGap)&&(!after||!Number.isFinite(after.p)||after.t-p.t>maxGap)}).map(p=>`<circle cx="${x(p.t)}" cy="${y(p.p)}" r="1.5" fill="${seriesInk(s.color)}"/>`).join(''):'';
    return `${region}<path class="series-line" d="${path}" stroke="${seriesInk(s.color)}" ${si>1?'stroke-dasharray="5 3"':''}/>${isolated}`;
  }).join('');
  const endLabels=(narrow||square)?'':last.map((d,i)=>`<path d="M${x(d.p.t)},${y(d.p.p)} L${L+W+12},${labelYs[i]} h8" fill="none" stroke="${seriesInk(d.s.color)}" stroke-width=".8"/><text class="end-label" x="${L+W+25}" y="${labelYs[i]+4}" style="fill:${labelInk(d.s.color)}">${esc(d.s.name==='Flávio Bolsonaro'?'F. Bolsonaro':d.s.name)} ${market?marketPct(d.p.p):d.p.p.toFixed(1)+(unit==='%'?'%':'')}</text>`).join('');
  host.innerHTML=`<svg class="chart-svg" width="${width}" height="${H}" viewBox="0 0 ${width} ${H}" role="img" aria-label="${esc(title)}. Exact values available in the chart readout and data table."><g>${grid.join('')}${axis}</g>${threshold!==null?`<line x1="${L}" x2="${L+W}" y1="${y(threshold)}" y2="${y(threshold)}" stroke="var(--chart-reference)" stroke-dasharray="4 5"/><text x="${L+6}" y="${y(threshold)-7}">50% reference</text>`:''}${paths}${endLabels}<g class="chart-guide" hidden><line class="guide" x1="${L}" x2="${L}" y1="${T}" y2="${H-B}"/><g class="chart-tooltip-points"></g></g></svg><div class="chart-readout" aria-live="polite" aria-atomic="true"></div><p class="chart-hint">${market?'Observation times may differ by series. ':''}Move across the chart to inspect · focus the chart and use ← / →</p>`;
  const svg=$('svg',host);svg.setAttribute('tabindex','0');svg.setAttribute('aria-label',title+'. Use left and right arrow keys to inspect observations.');
  const times=[...new Set(observations.map(p=>p.t))].sort((a,b)=>a-b);let index=times.length-1;
  const readout=$('.chart-readout',host),guide=$('.chart-guide',host);
  function show(t,visible=true){
    guide.hidden=!visible;guide.removeAttribute('hidden');guide.style.display=visible?'':'none';
    $('.guide',host).setAttribute('x1',x(t));$('.guide',host).setAttribute('x2',x(t));let dots='';
    readout.innerHTML=`<strong>${market?'As of '+stamp(t):date(t,true)}</strong>`+series.map(s=>{
      const exact=market?[...s.points].reverse().find(p=>p.t<=t&&Number.isFinite(p.p)):s.points.find(p=>p.t===t&&Number.isFinite(p.p));
      if(exact)dots+=`<circle cx="${x(exact.t)}" cy="${y(exact.p)}" r="4" fill="${seriesInk(s.color)}"/>`;
      return `<span><i class="swatch" style="--series:${seriesInk(s.color)}"></i>${esc(s.name)} <strong>${exact?(market?marketPct(exact.p):exact.p.toFixed(1)+(unit==='%'?'%':' p.p.')):'—'}</strong>${market&&exact?` <span class="observation-time">(${stamp(exact.t)})</span>`:''}</span>`;
    }).join('');$('.chart-tooltip-points',host).innerHTML=dots;
  }
  show(times.at(-1),false);
  svg.addEventListener('pointermove',e=>{const rect=svg.getBoundingClientRect(),px=(e.clientX-rect.left)*width/rect.width;const target=start+Math.max(0,Math.min(1,(px-L)/W))*(end-start);index=times.reduce((best,t,i)=>Math.abs(t-target)<Math.abs(times[best]-target)?i:best,0);show(times[index]);});
  svg.addEventListener('pointerleave',()=>show(times[index],false));
  svg.addEventListener('focus',()=>show(times[index]));
  svg.addEventListener('blur',()=>show(times[index],false));
  svg.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();index=e.key==='Home'?0:e.key==='End'?times.length-1:Math.max(0,Math.min(times.length-1,index+(e.key==='ArrowRight'?1:-1)));show(times[index]);}});
}
function addResize(render){let timer;window.addEventListener('resize',()=>{clearTimeout(timer);timer=setTimeout(render,120)});}
function observationTable(series,limit=100){const rows=seriesCSV(series);return `<div class="table-scroll"><table><caption class="table-caption">${rows.length-1} observation timestamps. ${rows.length-1>limit?`Latest ${limit} shown; CSV includes the entire selection.`:''} Blank cells are unavailable, not zero.</caption><thead><tr>${rows[0].map(x=>`<th>${esc(x.replace('timestamp_utc','Timestamp (UTC)'))}</th>`).join('')}</tr></thead><tbody>${rows.slice(1).reverse().slice(0,limit).map(row=>`<tr>${row.map((v,i)=>`<td>${i? (v===''?'—':marketPct(Number(v))):esc(v.replace('T',' ').slice(0,19))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}

function drawForecast(){
  const host=$('#forecast-chart'),size=Math.max(280,host.clientWidth);
  const lula=runoffForecast.find(d=>d.id==='lula'),flavio=runoffForecast.find(d=>d.id==='flavio');
  const cx=size/2,cy=size*.57,r=size*.38,thickness=Math.min(42,size*.085);
  const point=(share,radius=r)=>[cx-radius*Math.cos(Math.PI*share/100),cy-radius*Math.sin(Math.PI*share/100)];
  const arc=(from,to,radius=r)=>{const a=point(from,radius),b=point(to,radius);return `M${a[0]},${a[1]} A${radius},${radius} 0 0 1 ${b[0]},${b[1]}`};
  const radial=(share,inner,outer)=>{const a=point(share,inner),b=point(share,outer);return `M${a[0]},${a[1]}L${b[0]},${b[1]}`};
  const text=(x,y,label,anchor='middle',fill='var(--muted)',cls='')=>`<text class="${cls}" x="${x}" y="${y}" text-anchor="${anchor}" fill="${fill}">${esc(label)}</text>`;
  const intervalRadius=r+thickness/2+12;
  let marks=text(cx,18,'Expected second-round valid votes');
  marks+=`<path class="runoff-arc lula-arc" d="${arc(0,lula.mean)}" fill="none" stroke="${seriesInk(lula.color)}" stroke-width="${thickness}"><title>Lula: ${pct(lula.mean)} expected valid votes</title></path>`;
  marks+=`<path class="runoff-arc flavio-arc" d="${arc(lula.mean,100)}" fill="none" stroke="${seriesInk(flavio.color)}" stroke-width="${thickness}"><title>Flávio Bolsonaro: ${pct(flavio.mean)} expected valid votes</title></path>`;
  marks+=`<path d="${radial(lula.mean,r-thickness/2,r+thickness/2)}" stroke="var(--paper)" stroke-width="3"/>`;
  marks+=`<path class="runoff-ci" d="${arc(lula.low,lula.high,intervalRadius)}" fill="none" stroke="var(--ink)" stroke-width="3"/>`;
  marks+=`<path d="${radial(lula.low,intervalRadius-5,intervalRadius+5)} ${radial(lula.high,intervalRadius-5,intervalRadius+5)}" fill="none" stroke="var(--ink)" stroke-width="2"/>`;
  marks+=`<path d="${radial(50,r-thickness/2-16,r+thickness/2+23)}" stroke="var(--muted)" stroke-width="1" stroke-dasharray="3 3"/>`;
  marks+=text(cx,cy-r+thickness/2+38,'50%');
  marks+=text(cx,cy-43,'Projected winner · mock')+text(cx,cy-16,lula.name,'middle',labelInk(lula.color),'runoff-winner');
  const left=28,right=size-28;
  marks+=text(left,cy+35,lula.name,'start',labelInk(lula.color))+text(right,cy+35,flavio.name,'end',labelInk(flavio.color));
  marks+=text(left,cy+62,pct(lula.mean),'start',labelInk(lula.color),'runoff-mean')+text(right,cy+62,pct(flavio.mean),'end',labelInk(flavio.color),'runoff-mean');
  marks+=text(left,cy+87,`${pct(lula.low)}–${pct(lula.high)}`,'start')+text(right,cy+87,`${pct(flavio.low)}–${pct(flavio.high)}`,'end');
  marks+=text(left,cy+110,'95% interval','start')+text(right,cy+110,'95% interval','end');
  host.innerHTML=`<svg class="forecast-svg semicircle-forecast" width="${size}" height="${size}" viewBox="0 0 ${size} ${size}" role="img" aria-label="Illustrative second-round election semicircle. Lula on the left: ${pct(lula.mean)}, 95% interval ${pct(lula.low)} to ${pct(lula.high)}. Flávio Bolsonaro on the right: ${pct(flavio.mean)}, 95% interval ${pct(flavio.low)} to ${pct(flavio.high)}. The outer bracket marks uncertainty in the shared boundary. Both intervals cross 50%.">${marks}</svg>`;
}
function home(){
  $('#main').innerHTML=intro('The expected second-round result.','Lula × Flávio Bolsonaro. Expected election-day vote shares, with uncertainty—not a first-round forecast.')+`
    <section class="forecast-stage">
      <div class="figure-heading"><div><h2>Projected winner: Lula <span class="winner-qualifier">· mock result</span></h2><p>51.9% vs 48.1% of valid votes. Both intervals cross 50%; the outcome remains uncertain.</p></div></div>
      <div class="forecast-grid">
        <figure><div id="forecast-chart"></div><figcaption><strong>Semicircle: 100% of valid votes. Top marker: 50%.</strong><p>The outer bracket marks the illustrative 95% range for the shared boundary between candidates. Each candidate’s interval is also written below the arc. These are complementary vote shares, not independent ranges or win probabilities.</p><p>All values are synthetic. Production will use validated election-day predictive intervals.</p></figcaption></figure>
        <figure class="forecast-art"><img src="assets/runoff-painting-v1.png" width="1254" height="1254" alt="Modern gouache still life with overlapping purple and teal translucent sheets on a white desk."><figcaption>Two possible outcomes. Original AI-generated editorial painting; decorative, not a representation of the data.</figcaption></figure>
      </div>
      <div class="table-scroll"><table class="forecast-values"><caption>Second round · election-day forecast fixture · valid votes · not a current-poll estimate</caption><thead><tr><th>Candidate</th><th class="num">Expected vote</th><th class="num">95% interval</th><th>Reading</th></tr></thead><tbody>${runoffForecast.map((d,i)=>`<tr><td>${d.name}</td><td class="num">${pct(d.mean)}</td><td class="num">${pct(d.low)}–${pct(d.high)}</td><td>${i?'Trailing at the expected value':'Projected winner at the expected value'}</td></tr>`).join('')}</tbody></table></div>
    </section>
    <section class="below-figure"><div><h3>A projected winner, not a certain winner.</h3><p>Vote share and probability of winning are different quantities. These are mock vote-share estimates; no numerical win probability is implied. The two candidates’ outcomes are complementary, not independent.</p></div><div class="links">${link('second-round.html','Explore the runoff',true)}${link('methodology.html#forecast','How the forecast will work')}</div></section>`;
  drawForecast();addResize(drawForecast);
}
function pollTrends(round){
  const second=round===2,all=second?secondSeries:firstSeries;let range='All',uncertainty=true,institute='all';
  const selected=new Set(all.map(s=>s.id));
  $('#main').innerHTML=intro(second?'The leading runoff.':'How the first round is taking shape.',second?'Only the two leading first-round candidates. Their head-to-head trend, with the uncertainty kept in view.':'Follow the expected vote share of each candidate over time. Inspect the trend without losing sight of the underlying uncertainty.')+`
    <div class="toolbar"><label class="field">Institute <select id="trend-institute"><option value="all">All institutes</option>${institutes.map(d=>`<option value="${d.id}">${d.name}</option>`).join('')}</select></label>${segment('Trend period',['3 months','6 months','All'],'All')}<label class="check-label"><input type="checkbox" id="uncertainty" checked> Show illustrative uncertainty</label></div>
    <p id="institute-status" class="table-status" aria-live="polite">All institutes · synthetic series</p>
    <div class="chart-legend">${all.map(s=>`<label class="check-label"><input type="checkbox" value="${s.id}" checked><i class="swatch" style="--series:${seriesInk(s.color)}"></i>${esc(s.name)}</label>`).join('')}</div>
    <div class="trend-grid">
      <section class="chart-panel"><div class="figure-heading"><div><h2>${second?'Lula × Flávio Bolsonaro':'The leading candidates'}</h2><p>Expected valid-vote share · ${second?'30–65% detail scale':'0–60% scale'}</p></div></div>${chartShell('poll-chart')}</section>
      <section class="chart-panel"><div class="figure-heading"><div><h2>${second?'The distance between the leaders':'The remaining candidates'}</h2><p>${second?'Flávio minus Lula · −8 to +8 percentage points':'Expected valid-vote share · 0–12% detail scale'}</p></div></div>${chartShell(second?'lead-chart':'other-chart')}</section>
    </div>
    <p class="scale-note">${second?'The vote-share chart shows percentages; the lead chart shows Flávio minus Lula. Positive differences favour Flávio; negative differences favour Lula.':'Both panels use the same dates but different vertical scales. Compare percentages—not the visual height of lines across panels.'}</p>
    ${sourceFooter('Source: synthetic design fixtures. Shaded bands are illustrative ranges, not calibrated intervals.',downloadButton('poll-csv')+link('database.html?round='+round,'View individual polls'))}
    <details><summary>Inspect chart values</summary><div id="poll-values"></div></details>
    <section class="insight-row"><div><h3>${second?'One pairing, a clear comparison.':'A trend is more useful than a headline.'}</h3><p>${second?'This view is deliberately limited to the two first-round leaders. Candidate selection and the eventual model will be driven by the verified data, not by this prototype.':'The final product will distinguish published polls from the estimated trend. These lines currently connect synthetic values and contain no forecasting model.'}</p></div><div><h3>Uncertainty belongs in the picture.</h3><p>The shaded range demonstrates how uncertainty could be shown. Its width is a visual placeholder; it must not be interpreted as a confidence or prediction interval.</p></div></section>`;
  function filtered(){return instituteSeries(round,institute).filter(s=>selected.has(s.id)).map(s=>({...s,points:s.points.filter(p=>range==='All'||p.t>=Date.UTC(2026,8,19)-(range==='3 months'?92:183)*86400000)}));}
  function render(){
    const series=filtered(),leaders=series.filter(s=>['lula','flavio'].includes(s.id));
    $('#institute-status').textContent=(institute==='all'?'All institutes':institutes.find(d=>d.id===institute).name)+' · synthetic series';
    drawChart($('#poll-chart'),leaders,{min:second?30:0,max:second?65:60,step:second?5:10,band:uncertainty,threshold:second?50:null,square:true,title:second?'Illustrative runoff vote-share trend':'Illustrative first-round leaders vote-share trends'});
    $('#poll-values').innerHTML=observationTable(series);
    if(second){const source=instituteSeries(round,institute);const lead={name:'Flávio minus Lula',color:'#328088',points:source[0].points.map((p,i)=>({t:p.t,p:flavioMinusLula(source[1].points[i].p,p.p)})).filter(p=>range==='All'||p.t>=Date.UTC(2026,8,19)-(range==='3 months'?92:183)*86400000)};drawChart($('#lead-chart'),[lead],{min:-8,max:8,step:4,unit:'pp',square:true,title:'Illustrative runoff lead: Flávio minus Lula in percentage points'});}
    else drawChart($('#other-chart'),series.filter(s=>!['lula','flavio'].includes(s.id)),{min:0,max:12,step:3,square:true,title:'Illustrative other first-round candidates vote-share trends'});
  }
  $$('.segmented button').forEach(b=>b.addEventListener('click',()=>{range=b.dataset.range;$$('.segmented button').forEach(x=>x.setAttribute('aria-pressed',x===b));render()}));
  $$('.chart-legend input').forEach(input=>input.addEventListener('change',()=>{input.checked?selected.add(input.value):selected.delete(input.value);render()}));
  $('#trend-institute').addEventListener('change',e=>{institute=e.target.value;render()});
  $('#uncertainty').addEventListener('change',e=>{uncertainty=e.target.checked;render()});$('#poll-csv').addEventListener('click',()=>csvDownload(`MOCK-round-${round}-${institute}-trends.csv`,seriesCSV(filtered())));render();addResize(render);
}

async function markets(){
  $('#main').innerHTML=intro('What the markets are pricing.','Two markets. Two independent views of the election. Contract prices are not vote shares, and neither is our forecast.','Archived market data')+`<div id="market-panels"><div class="loading" role="status">Loading the archived market snapshots…</div></div><section class="insight-row"><div><h3>Read prices, not predictions of votes.</h3><p>These are archived “Yes” contract prices, multiplied by 100. Each market has its own settlement rules, liquidity and candidate selection. The displayed series need not add up to 100%.</p></div><div><h3>The snapshot is deliberately fixed.</h3><p>This local prototype uses the same JSON snapshots inspected on the existing site. No live market requests or update jobs are connected. Missing observations are left missing; long gaps break the line.</p></div></section>`;
  const results=await Promise.allSettled(['kalshi','polymarket'].map(async id=>{const res=await fetch(`data/${id}.json`);if(!res.ok)throw Error('Snapshot unavailable');return res.json()}));
  $('#market-panels').innerHTML='';
  results.forEach((result,i)=>{
    const id=i?'polymarket':'kalshi',name=i?'Polymarket':'Kalshi',panel=document.createElement('section');panel.className='market-panel';panel.id=id;$('#market-panels').append(panel);
    if(result.status==='rejected'){panel.innerHTML=`<div class="error-state"><h2>${name} snapshot unavailable</h2><p>The other chart can still be used. Check the local data file and reload.</p><button onclick="location.reload()">Reload page</button></div>`;return;}
    const data=result.value;let range='1M',view=[];const colorMap={'Lula':'#501C72','Luiz Inácio Lula da Silva':'#501C72','Flávio Bolsonaro':'#328088','Augusto Cury':'#A06425','Jair Bolsonaro':'#737C8E','Renan Santos':'#AD7DAC'};
    panel.innerHTML=`<div class="market-heading"><div><h2>${name}</h2><p>Presidential election winner · archived contract prices</p></div>${segment(name+' period',['1D','1W','1M','ALL'],'1M')}</div><div class="market-legend"></div>${chartShell(id+'-chart')}<p class="market-meta"></p>${sourceFooter('Source: '+name+' data from the existing Observer snapshot.',downloadButton(id+'-csv')+`<a class="text-link" href="${i?'https://polymarket.com/event/brazil-presidential-election':'https://kalshi.com/markets/kxbrpres/brazil-presidency'}" target="_blank" rel="noopener noreferrer">Open market ${arrow}</a>`)}<details><summary>Inspect prices and observation times</summary><div class="market-values"></div></details>`;
    function render(){const end=Number(data.cutoff),span=({['1D']:1,['1W']:7,['1M']:30})[range];const start=range==='ALL'?Math.min(...data.series.flatMap(s=>(i?s.ranges.ALL:s.points).map(p=>p.t))):end-span*86400000;
      view=data.series.map((s,k)=>({...s,name:s.name==='Luiz Inácio Lula da Silva'?'Lula':s.name,color:colorMap[s.name]||['#501C72','#328088','#A06425','#737C8E'][k],points:(i?(s.ranges?.[range]||[]):(range==='ALL'?s.points:s.hourly||s.points)).filter(p=>p.t>=start&&p.t<=end).sort((a,b)=>a.t-b.t)}));
      $('.market-legend',panel).innerHTML=view.map(s=>{const p=[...s.points].reverse().find(p=>Number.isFinite(p.p));return `<div><span class="name"><i class="swatch" style="--series:${seriesInk(s.color)}"></i>${esc(s.name)}</span><span class="value" style="color:${labelInk(s.color)}">${p?marketPct(p.p):'—'}</span><time>${p?stamp(p.t):'No observation in this period'}</time></div>`}).join('');
      drawChart($('#'+id+'-chart'),view,{min:0,max:100,step:20,market:true,square:true,maxGap:range==='ALL'?3*86400000:range==='1M'?18*3600000:4*3600000,domain:[start,end],title:name+' archived contract prices'});
      $('.market-meta',panel).textContent=`Snapshot cutoff: ${stamp(end)} · ${range==='ALL'?'Daily archive':i&&range==='1M'?'Six-hour source history':'Hourly source history'} · UTC throughout`;
      $('.market-values',panel).innerHTML=observationTable(view,80);
    }
    $$('.segmented button',panel).forEach(b=>b.addEventListener('click',()=>{range=b.dataset.range;$$('.segmented button',panel).forEach(x=>x.setAttribute('aria-pressed',x===b));render()}));
    $('#'+id+'-csv').addEventListener('click',()=>csvDownload(`${id}-ARCHIVED-${range}.csv`,seriesCSV(view)));render();addResize(render);
  });
}

function offenders(){
  let selected='A',election='All elections';
  $('#main').innerHTML=intro('A record of getting it wrong.','Compare historical polling errors, then inspect the evidence behind each institute. A ranking should invite scrutiny—not replace it.','Fictional scorecards')+`<div class="toolbar"><label class="field">Historical window <select id="election"><option>All elections</option><option>2022</option><option>2018</option><option>2014</option></select></label><p class="mock-note push">All institute names and scores below are fictional.</p></div><div class="offenders-layout"><section><div class="ranking-head"><h2>Largest historical errors</h2><span>Mean absolute error · p.p.</span></div><div id="ranking"></div><p class="table-status">Select an institute to inspect its scorecard. Higher error is worse.</p></section><aside id="scorecard" class="scorecard" aria-live="polite"></aside></div><section class="distance-section"><div class="figure-heading"><div><h2>Distance from the Observer estimate</h2><p>Latest raw second-round poll versus our PNAD + bias-corrected estimate at that poll’s publication date. Before any election-day projection.</p></div><label class="field">Candidate <select id="distance-candidate"><option value="lula">Lula</option><option value="flavio">Flávio Bolsonaro</option></select></label></div><p class="comparison-explainer">Least to greatest distance, adjusted for the published margin of error: |raw poll − corrected Observer estimate| ÷ margin of error. A value of 1× means one published margin away. All figures and institute names are synthetic.</p><div id="distances" aria-live="polite"></div>${sourceFooter('Matched scenario: Lula × Flávio, total respondents on both sides. A different dated benchmark is used for each latest poll. No Monte Carlo projection. This descriptive distance is not a significance test: the Observer estimate also has uncertainty and may share poll inputs.',link('methodology.html#institute-errors','How institutes will be evaluated'))}</section>`;
  function error(d){return +(d.error*(election==='All elections'?1:election==='2022'?.92:election==='2018'?1.13:.85)).toFixed(1)}
  function render(){const ranking=[...institutes].sort((a,b)=>error(b)-error(a));$('#ranking').innerHTML=ranking.map((d,i)=>`<button class="rank-row" data-institute="${d.id}" aria-pressed="${d.id===selected}"><span class="rank-number">${String(i+1).padStart(2,'0')}</span><span><span class="rank-name">${d.name}</span><span class="rank-bar" style="--size:${error(d)/8*100}%;display:block"></span></span><span class="rank-error">${error(d).toFixed(1)} <small>p.p.</small></span></button>`).join('');
    const d=institutes.find(x=>x.id===selected);$('#scorecard').innerHTML=`<div class="score-top"><div><span class="badge">Illustrative scorecard</span><h2>${d.name}</h2></div><span class="grade" aria-label="Mock grade ${d.grade}">${d.grade}</span></div><dl class="score-metrics"><div><dt>Historical mean absolute error</dt><dd>${error(d).toFixed(1)} p.p.</dd></div><div><dt>Signed mean error</dt><dd>${signed(d.bias)} p.p.</dd></div><div><dt>Intervals covering the result</dt><dd>${d.calibration}%</dd></div><div><dt>Polls in comparison</dt><dd>${election==='All elections'?d.coverage:Math.max(4,Math.round(d.coverage/3))}</dd></div><div><dt>Historical window</dt><dd>${election}</dd></div></dl><p>This is a fictional institute and a design-only grade. The final scorecard will show matched election horizons, sample coverage, uncertainty and linked source records. It will not infer quality from a single miss.</p>${link('methodology.html#institute-errors','Read the evaluation framework')}`;
    $$('.rank-row').forEach(b=>b.addEventListener('click',()=>{selected=b.dataset.institute;render();$(`[data-institute="${selected}"]`).focus({preventScroll:true})}));
  }
  function distance(){
    const candidate=$('#distance-candidate').value,rows=currentComparisons(polls,candidate);
    $('#distances').innerHTML=`<div class="table-scroll"><table class="comparison-table"><caption>Current distance · smallest first · total respondents · benchmark version MOCK-current-v1</caption><thead><tr><th>Order / institute</th><th>Latest poll / fieldwork</th><th class="num">Raw poll ± MoE</th><th class="num">Corrected Observer</th><th class="num">Signed gap</th><th class="num">Distance / MoE</th><th class="num">Beyond MoE</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${r.distance===null?'—':i+1+'.'} ${esc(r.poll.institute)}</td><td>${date(r.poll.date,true)}<span class="table-muted">${date(r.poll.fieldStart)}–${date(r.poll.fieldEnd)} · ${r.poll.id}</span></td><td class="num">${pct(r.raw)} ± ${r.poll.moe.toFixed(1)} p.p.</td><td class="num">${r.corrected===undefined?'Unavailable':pct(r.corrected)}<span class="table-muted">As of ${date(r.poll.date)}</span></td><td class="num">${r.difference===null?'—':signed(r.difference)+' p.p.'}</td><td class="num"><strong>${r.distance===null?'Not ranked':r.distance.toFixed(2)+'×'}</strong><span class="table-muted">${r.distance===null?'Missing comparable input':r.distance<=1?'Within published margin':'Beyond published margin'}</span></td><td class="num">${r.excess===null?'—':r.excess.toFixed(1)+' p.p.'}</td></tr>`).join('')}</tbody></table></div><p class="comparison-explainer">Signed gap = raw poll minus corrected Observer. “Beyond MoE” is the portion of the absolute gap outside the published margin, not proof of bias. Raw values are taken directly from each institute’s latest record in the ${link('database.html?round=2','second-round database')}.</p>`;
  }
  $('#election').addEventListener('change',e=>{election=e.target.value;render()});$('#distance-candidate').addEventListener('change',distance);render();distance();
}

function database(){
  let round=new URLSearchParams(location.search).get('round')==='2'?2:1,query='',institute='All institutes',order='newest',currentRows=[];
  $('#main').innerHTML=intro('The evidence, row by row.','Inspect individual polls, their fieldwork and their reported results. The records below are synthetic examples of the future database.')+`<div class="database-tabs" role="tablist" aria-label="Poll round"><button id="tab-1" role="tab" data-round="1" aria-controls="database-panel">First-round polls</button><button id="tab-2" role="tab" data-round="2" aria-controls="database-panel">Second-round polls</button></div><section role="tabpanel" id="database-panel"><div class="database-toolbar"><label class="field">Search polls <input class="search-field" id="poll-search" type="search" placeholder="Institute or record ID…"></label><label class="field">Institute <select id="institute-filter"><option>All institutes</option>${institutes.map(d=>`<option>${d.name}</option>`).join('')}</select></label><label class="field">Order <select id="poll-order"><option value="newest">Newest first</option><option value="oldest">Oldest first</option></select></label><button class="push" id="reset-filters">Reset filters</button><button id="database-csv">Download CSV</button></div><p class="table-status" id="record-count" aria-live="polite"></p><div id="poll-table"></div><div id="record-details" class="record-details" hidden tabindex="-1"></div></section><section class="insight-row"><div><h3>Published percentages stay intact.</h3><p>Individual records show reported values on their original denominator. Blank, null and undecided responses are not silently redistributed. The charted trend will be a separate, versioned output.</p></div><div><h3>A traceable record for every poll.</h3><p>The production database will link the source report, TSE registration and any corrections. These demo IDs do not refer to real registrations.</p></div></section>`;
  function render(){
    $$('.database-tabs button').forEach(b=>{b.setAttribute('aria-selected',Number(b.dataset.round)===round);b.tabIndex=Number(b.dataset.round)===round?0:-1});$('#database-panel').setAttribute('aria-labelledby','tab-'+round);
    currentRows=polls.filter(p=>p.round===round&&(institute==='All institutes'||p.institute===institute)&&`${p.institute} ${translate(p.institute)} ${p.id}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>order==='newest'?b.date.localeCompare(a.date):a.date.localeCompare(b.date));
    $('#record-count').textContent=`${currentRows.length} illustrative ${round===1?'first':'second'}-round records · Published percentages, total respondents · Fictional institutes`;
    $('#record-details').hidden=true;$('#database-csv').disabled=!currentRows.length;
    if(!currentRows.length){$('#poll-table').innerHTML='<div class="empty-state"><h3>No polls match these filters.</h3><p>Try a different institute or reset the filters.</p></div>';return;}
    $('#poll-table').innerHTML=`<div class="table-scroll"><table><caption class="screen-reader">Individual ${round===1?'first':'second'}-round polls. All records are fictional.</caption><thead><tr><th>Institute / publication</th><th>Fieldwork</th><th class="num">Lula</th><th class="num">F. Bolsonaro</th><th class="num">${round===1?'Other responses':'Other / undecided'}</th><th class="num">Sample</th><th>Record</th></tr></thead><tbody>${currentRows.map(p=>`<tr><td>${p.institute}<span class="table-muted">${date(p.date,true)}</span></td><td>${date(p.fieldStart)} – ${date(p.fieldEnd)}<span class="table-muted">${p.method}</span></td><td class="num">${pct(p.lula)}</td><td class="num">${pct(p.flavio)}</td><td class="num">${pct(100-p.lula-p.flavio)}</td><td class="num">${p.sample.toLocaleString(locale)}</td><td><button class="table-button" data-record="${p.id}">${p.id}</button></td></tr>`).join('')}</tbody></table></div>`;
    $$('[data-record]').forEach(b=>b.addEventListener('click',()=>showRecord(b.dataset.record)));
  }
  function showRecord(id){const p=polls.find(x=>x.id===id);const panel=$('#record-details');panel.hidden=false;panel.innerHTML=`<div class="record-heading"><div><span class="badge">Synthetic record</span><h3 style="margin-top:8px">${p.institute} · ${p.id}</h3></div><button id="close-record" aria-label="Close record details">Close</button></div><dl><div><dt>Publication</dt><dd>${date(p.date,true)}</dd></div><div><dt>Fieldwork</dt><dd>${date(p.fieldStart)}–${date(p.fieldEnd,true)}</dd></div><div><dt>Round</dt><dd>${p.round===1?'First round':'Lula × Flávio Bolsonaro'}</dd></div><div><dt>Sample</dt><dd>${p.sample.toLocaleString(locale)} respondents</dd></div><div><dt>Method</dt><dd>${p.method}</dd></div><div><dt>Published margin (mock)</dt><dd>±${p.moe.toFixed(1)} p.p.</dd></div></dl><p>No real poll report or TSE registration is attached to this design fixture. Production records will preserve the source URL, archived report, demographic disclosures and correction history.</p>`;panel.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});panel.focus({preventScroll:true});$('#close-record').addEventListener('click',()=>{panel.hidden=true;$(`[data-record="${id}"]`).focus()});}
  $$('.database-tabs button').forEach(b=>{b.addEventListener('click',()=>{round=Number(b.dataset.round);history.replaceState(null,'',`${location.pathname}?round=${round}`);render()});b.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();round=round===1?2:1;render();$('#tab-'+round).focus();history.replaceState(null,'',`${location.pathname}?round=${round}`)}})});
  $('#poll-search').addEventListener('input',e=>{query=e.target.value;render()});$('#institute-filter').addEventListener('change',e=>{institute=e.target.value;render()});$('#poll-order').addEventListener('change',e=>{order=e.target.value;render()});$('#reset-filters').addEventListener('click',()=>{query='';institute='All institutes';order='newest';$('#poll-search').value='';$('#institute-filter').value=institute;$('#poll-order').value=order;render()});$('#database-csv').addEventListener('click',()=>{const keys=['id','round','institute','date','fieldStart','fieldEnd','sample','method','lula','flavio','moe','status'];csvDownload(`MOCK-round-${round}-individual-polls.csv`,[keys,...currentRows.map(p=>keys.map(k=>p[k]))])});render();
}

function methodology(){
  const sections=[['reading','What each number means'],['collection','Collecting the evidence'],['normalization','Making polls comparable'],['demographics','Demographic correction'],['institute-errors','Learning from past errors'],['forecast','From polls to a forecast'],['uncertainty','Showing uncertainty'],['markets','Keeping markets separate'],['audit','A reproducible record']];
  $('#main').innerHTML=intro('Show the work.','A clear route from a published poll to an estimate—with the assumptions, limits and evidence left visible.','Proposed methodology')+`<div class="method-layout"><nav class="method-toc" aria-label="Methodology contents"><p>IN THIS EXPLANATION</p>${sections.map(([id,title])=>`<a href="#${id}">${title}</a>`).join('')}</nav><article class="method-article"><section id="reading"><h2>What each number means</h2><p class="status-note"><strong>This is the proposed framework, not an operating model.</strong> This version tests the website’s design. Forecasts, polling trends, uncertainty bands and institute scores are illustrative. The market pages use existing archived snapshots.</p><div class="method-step"><strong>Published poll</strong><span>What respondents said in one survey, using that survey’s own denominator.</span></div><div class="method-step"><strong>Current estimate</strong><span>A model’s estimate of opinion now, without projecting to election day.</span></div><div class="method-step"><strong>Forecast</strong><span>An election-day estimate, with additional uncertainty about what may change.</span></div><div class="method-step"><strong>Market price</strong><span>The price of a contract with its own outcome and settlement rules. Never a vote share.</span></div></section><section id="collection"><h2>Collecting the evidence</h2><p>Each poll will have a source report, publication date, fieldwork dates, institute identity, sample, interview method, geographic scope and election scenario. Where applicable, the record will link to its <a href="https://pesqele-divulgacao.tse.jus.br/app/pesquisa/listar.xhtml" target="_blank" rel="noopener noreferrer">TSE registration</a>.</p><p>Registration is evidence that a survey was registered—not proof that a result was published or independently validated. Pending registrations remain separate until the relevant result is found and checked.</p><p>Original files and retrieval dates will be preserved. Duplicate releases, sponsored institute-name variants and corrections will be linked to the same canonical record rather than counted as new polls.</p></section><section id="normalization"><h2>Making polls comparable</h2><p>First-round and second-round scenarios remain separate. So do total-respondent percentages and valid-vote percentages. We will retain blank, null and undecided categories, rather than silently allocating them to candidates.</p><p>The fieldwork midpoint locates a poll in time. The model will also retain the fieldwork duration, sample design and mode. Published sampling margins are not a complete measure of total polling error.</p><p>The first prototype’s trend lines are synthetic. No house-effect model, weighting scheme or statistical smoothing has been implemented.</p></section><section id="demographics"><h2>Demographic correction, where justified</h2><p>More recent population figures do not automatically make a poll correctable. The target must match the survey’s universe: resident population, eligible voters, registered electorate or likely voters are different populations.</p><p>The proposed benchmark sources are <a href="https://www.ibge.gov.br/estatisticas/sociais/trabalho/17270-pnad-continua.html" target="_blank" rel="noopener noreferrer">IBGE’s PNAD Contínua</a> and, when the target is the registered electorate, <a href="https://www.tse.jus.br/eleitor/estatisticas-de-eleitorado" target="_blank" rel="noopener noreferrer">TSE electorate statistics</a>.</p><ul><li><strong>Published cross-tabs:</strong> complete subgroup vote shares and compatible subgroup weights may support a one-variable standardization or a sensitivity analysis.</li><li><strong>Marginals alone:</strong> age, education and region tables do not reveal how those characteristics overlap. Combining them is not equivalent to correcting the individual respondents.</li><li><strong>Microdata:</strong> joint demographic adjustment requires respondent-level information or sufficiently detailed joint cells, original weights and design information.</li></ul><p>Any correction will disclose the available inputs, assumptions, weight limits and uncertainty. When evidence is insufficient, the result stays uncorrected and the limitation stays visible.</p></section><section id="institute-errors"><h2>Learning from past errors</h2><p>The historical ranking will compare polls with certified outcomes at matched points in the election cycle. A poll months before an election should not be judged as though it were a final-week forecast.</p><p>Each scorecard will separate absolute error, signed error, interval coverage and the number of comparable observations. Election, round, geographic scope and vote denominator must match. A small evidence base will not support a confident quality grade.</p><p>Institute-specific tendencies—often called house effects—will be estimated with partial pooling. This allows shared information without assuming that one historical miss proves a permanent bias.</p><p>The distance-to-Observer view takes each institute’s latest raw published second-round result and compares it with the PNAD- and house-bias-corrected Observer estimate as of that same publication date, before any election-day or Monte Carlo projection. Both sides use the same candidate pairing and total-respondent denominator. The publication date is the comparison cutoff; fieldwork dates remain visible. Production comparisons must use only inputs available by that cutoff.</p><p>The current-distance ranking runs from smallest to largest absolute difference divided by the published margin of error. It also displays the signed percentage-point gap and the excess outside the margin. Missing margins or incompatible benchmarks are not ranked. This descriptive ratio is not a z-score or significance test: the benchmark is uncertain, and shared poll inputs can induce dependence. Historical errors remain a separate, largest-first ranking. Distance is disagreement, not proof that an institute is wrong. All institute names, corrected benchmarks and grades here are fictional.</p></section><section id="forecast"><h2>From polls to a forecast</h2><p>The proposed system combines a latent opinion trend with polling error, mode and institute effects, then adds election-day uncertainty. First-round vote shares must remain non-negative and sum to the defined total.</p><p>Turnout and undecided-voter behaviour will be treated as uncertain scenarios, not fixed redistributions. Second-round modelling on this site is restricted to the two leading first-round candidates, as specified in the product brief.</p><p>Monte Carlo simulations will draw shared election-wide errors, correlated institute or mode errors and candidate-level variation. Polls are not independent merely because they come from different institutes.</p><p>Expected vote share and probability of victory are distinct outputs. The landing-page prototype shows illustrative second-round election-day vote shares, a projected winner at the expected value, and mock 95% intervals. These are design fixtures, not calibrated predictions.</p></section><section id="uncertainty"><h2>Showing uncertainty honestly</h2><p>Validation will replay historical elections using only the information available at each simulated cutoff. Rolling-origin backtests will prevent later data from leaking into earlier forecasts.</p><p>We will examine interval coverage, absolute errors, calibration and sensitivity to uncertain assumptions. A polished line or a large simulation count cannot compensate for a misspecified model.</p><p>Final intervals must include relevant sampling, non-sampling, demographic, turnout and future-change uncertainty. The prototype’s shaded bands are design placeholders and have no statistical coverage claim.</p></section><section id="markets"><h2>Keeping markets separate</h2><p>Kalshi and Polymarket remain a separate view of market prices. They will not be quietly averaged into the polling estimate or used as independent confirmation of it.</p><p>Every snapshot retains provider, contract, observation time, retrieval time and available resolution. Missing prices stay missing, and long gaps interrupt the line. Different market definitions and settlement rules limit direct comparisons.</p></section><section id="audit"><h2>A reproducible record</h2><p>Each published model run will record its input snapshot, source hashes, transformations, model version, parameters, random seed, simulation count and validation report. Corrections will have an explicit change log.</p><p>The proposed publishing chain separates raw evidence, cleaned data, model output and presentation. The current local prototype does not alter the Hostinger jobs, repository sync or production data.</p>${link('database.html','Inspect the prototype database',true)}</section></article></div>`;
}

